"""Random (now, start) pairs on a wrapping 32-bit counter, weighted towards
cases that force the counter to have wrapped between the two readings."""

UINT32_MAX = 0xFFFFFFFF


def generate(rng, count):
    builders = (_no_wrap, _wrapped, _near_boundary, _anything)
    return [builders[i % len(builders)](rng, i + 1) for i in range(count)]


def _case(name, now, start, description=""):
    return {
        "name": name,
        "stdin": "%d %d\n" % (now, start),
        "description": description,
    }


def _no_wrap(rng, index):
    start = rng.randint(0, UINT32_MAX - 100000)
    elapsed = rng.randint(0, 100000)
    return _case("no wraparound in this interval #%d" % index,
                 start + elapsed, start)


def _wrapped(rng, index):
    start = rng.randint(UINT32_MAX - 100000, UINT32_MAX)
    elapsed = rng.randint(1, 100000)
    now = (start + elapsed) % (UINT32_MAX + 1)
    return _case("the counter wraps once inside this interval #%d" % index,
                 now, start,
                 "start is close to the top of the range and now has "
                 "already wrapped past 0.")


def _near_boundary(rng, index):
    start = rng.randint(0, UINT32_MAX)
    now = (start - 1) % (UINT32_MAX + 1)
    return _case("one tick short of a full lap #%d" % index, now, start,
                 "The true elapsed count is UINT32_MAX -- the largest "
                 "value the function can return.")


def _anything(rng, index):
    return _case("two unrelated readings #%d" % index,
                 rng.randint(0, UINT32_MAX), rng.randint(0, UINT32_MAX))
